param([ValidatePattern('^[a-z0-9-]+$')][string]$Cluster='ai-k8s',[ValidateSet('enabled','disabled')][string]$Redis='disabled',[ValidateSet('enabled','disabled')][string]$Kafka='disabled',[ValidateSet('enabled','disabled')][string]$MinIO='disabled',[ValidateSet('enabled','disabled')][string]$Kyverno='disabled')
$ErrorActionPreference='Stop';$ctx="kind-$Cluster";$root=Resolve-Path (Join-Path $PSScriptRoot '..')
foreach($item in @(@('Redis',$Redis,'redis'),@('Kafka',$Kafka,'kafka'),@('MinIO',$MinIO,'minio'))){if($item[1]-eq'enabled'){kubectl --context $ctx apply -f (Join-Path $root "components/$($item[2]).yaml");if($LASTEXITCODE-ne 0){throw "$($item[0]) apply failed."};kubectl --context $ctx -n data rollout status "deployment/$($item[2])" --timeout=300s}}
if($Kyverno-eq'enabled){helm repo add kyverno https://kyverno.github.io/kyverno/ --force-update;helm repo update;helm upgrade --install kyverno kyverno/kyverno --kube-context $ctx -n kyverno --create-namespace;if($LASTEXITCODE-ne 0){throw 'Kyverno install failed.'};kubectl --context $ctx -n kyverno rollout status deployment/kyverno-admission-controller --timeout=300s}
kubectl --context $ctx get pods -A
